/**
 * Build-time configuration for code-signed over-the-air updates (plan section 35.6). Node only: app.config.js and the
 * update scripts use it; app code never does.
 *
 * The app uses expo-updates against EAS Update (https://u.expo.dev/<project id>) with mandatory code signing, after
 * TrellisKit: the public certificate lives at updates/certificate.pem (generated by
 * scripts/generate-updates-certificate.js), and the private key never enters the repository. Without the
 * certificate, or without an EAS project id, the build has updates disabled and prints a warning.
 *
 * Environment:
 * - MYMORNINGNEWS_MOBILE_UPDATES_DISABLED=1: build without updates even when the certificate exists.
 *
 * Channels come from eas.json (each build profile sets `channel`), so preview and production binaries of one commit
 * share a runtime version (policy `fingerprint`) and differ only in the channel EAS writes into the native config.
 *
 * Key rotation: expo-updates embeds one certificate and one key id per binary. EAS Update signs each update with the
 * one private key given to `eas update --private-key-path` and does not send a certificate chain, so the standby-key
 * scheme TrellisKit uses with its own update server is not available. Rotation therefore needs a new binary; see
 * updates/README.md.
 */
const fs = require('fs');
const path = require('path');

/** Certificate location, relative to mobile/. */
const CertificateRelativePath = path.join('updates', 'certificate.pem');

/** Code signing metadata `eas update` signs with. */
const CodeSigningMetadata = Object.freeze({ keyid: 'main', alg: 'rsa-v1_5-sha256' });

function read(env, name) {
  return ((env && env[name]) || '').trim();
}

/**
 * The expo-updates part of the app config.
 * @param {object} options
 * @param {string} options.projectRoot Absolute mobile/ directory.
 * @param {string} options.projectId EAS project id, or '' when there is none yet.
 * @param {Record<string, string|undefined>} [options.env]
 * @returns {{ enabled: boolean, warning: string|null, updates: object, runtimeVersion: object, extra: object }}
 */
function updatesConfig({ projectRoot, projectId, env = process.env }) {
  const certificate = path.join(projectRoot, CertificateRelativePath);
  const runtimeVersion = { policy: 'fingerprint' };
  let warning = null;
  if (read(env, 'MYMORNINGNEWS_MOBILE_UPDATES_DISABLED') === '1') warning = 'Over-the-air updates are disabled by MYMORNINGNEWS_MOBILE_UPDATES_DISABLED=1.';
  else if (!projectId) warning = 'Over-the-air updates are disabled: no EAS project id (set MYMORNINGNEWS_MOBILE_EAS_PROJECT_ID).';
  else if (!fs.existsSync(certificate)) warning = 'Over-the-air updates are disabled: no code signing certificate at ' + certificate + '. Run: npm run updates-certificate';
  if (warning) {
    return { enabled: false, warning, runtimeVersion, updates: { enabled: false }, extra: { enabled: false } };
  }
  const url = 'https://u.expo.dev/' + projectId;
  return {
    enabled: true,
    warning: null,
    runtimeVersion,
    updates: {
      enabled: true,
      url,
      checkAutomatically: 'ON_LOAD',
      fallbackToCacheTimeout: 0,
      codeSigningCertificate: './' + CertificateRelativePath.split(path.sep).join('/'),
      codeSigningMetadata: { ...CodeSigningMetadata },
    },
    extra: { enabled: true, url },
  };
}

module.exports = { CertificateRelativePath, CodeSigningMetadata, updatesConfig };
